// brand.json is generated by brand/apply.py from the repo-level brand/brand.json.
import brandJson from "./brand.json";

type BrandColors = Record<string, string>;

export type Brand = {
  name: string;
  shortName: string;
  platformName: string;
  tagline: string;
  description: string;
  publisher: string;
  logoUrl: string;
  font: { family: string; googleFontsUrl?: string };
  radius: string;
  colors: { light: BrandColors; dark: BrandColors };
};

export const brand: Brand = brandJson;

function toCssVars(colors: BrandColors): string {
  return Object.entries(colors)
    .map(([key, value]) => `--ac-${key.replace(/[A-Z]/g, (c) => `-${c.toLowerCase()}`)}:${value};`)
    .join("");
}

/** CSS custom properties for both themes, injected once in the root layout. */
export function brandCss(): string {
  const font = `--ac-font:"${brand.font.family}",ui-sans-serif,system-ui,sans-serif;--ac-radius:${brand.radius};`;
  return `:root{${toCssVars(brand.colors.light)}${font}}.dark{${toCssVars(brand.colors.dark)}}`;
}
